using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup
builder.Services.AddSingleton<ModelTrainingService>();

var app = builder.Build();

// Train and evaluate before accepting requests
var trainer = app.Services.GetRequiredService<ModelTrainingService>();
trainer.TrainAndEvaluate();

// Register pooled prediction engine with the trained model
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainer.ModelPath);

// Rebuild the service provider to include the prediction pool
// Instead, register it upfront with a factory that defers to the model path
app = null!;

// Correct approach: register everything before building
var builder2 = WebApplication.CreateBuilder(args);
builder2.Services.AddControllers();
builder2.Services.AddSingleton<ModelTrainingService>();

// Train model eagerly to get the path
var tempProvider = builder2.Services.BuildServiceProvider();
var trainingService = tempProvider.GetRequiredService<ModelTrainingService>();
trainingService.TrainAndEvaluate();

builder2.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainingService.ModelPath);

var app2 = builder2.Build();
app2.MapControllers();
app2.Run();

